#!/usr/bin/env python3
"""Render the auto-generated state row in AGENTS.md from artifacts + state.

The Payload row in AGENTS.md §1 is the fact that goes stale every deploy
(version, md5, size, what the TV runs, what is owed).  This tool renders it
from two sources so no hand-editing is needed:

  * derivable from the repo: payload md5/size (server/payload.dll) and the
    shellcode blob size (tools/physrpc_shellcode.bin);
  * `docs/state.json` (tracked): everything only an operator session can know
    - version labels, deploy date, the live beacon token, what is still owed,
    and the measured memory facts.

    python tools/update_state.py --check   # exit 1 if the doc block drifted
    python tools/update_state.py --fix     # rewrite the marked block

`--check` runs as a test_all.py layer, so editing the payload without
refreshing the state fails the suite exactly the way test_constants.py fails
on a constant drift.  After a deploy session, update docs/state.json (version,
date, token, owed-notes) and run --fix; the artifacts-derived numbers are never
hand-written anywhere.
"""
import argparse
import hashlib
import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
AGENTS = ROOT / "AGENTS.md"
STATE = ROOT / "docs" / "state.json"
PAYLOAD = ROOT / "server" / "payload.dll"
BLOB = ROOT / "tools" / "physrpc_shellcode.bin"

BEGIN = "<!-- STATE:BEGIN (generated by tools/update_state.py --fix; edit docs/state.json, not this block) -->"
END = "<!-- STATE:END -->"


def payload_facts() -> dict:
    data = PAYLOAD.read_bytes()
    return {
        "md5": hashlib.md5(data).hexdigest(),
        "size": len(data),
        "blob_size": BLOB.stat().st_size,
    }


def render(state: dict, facts: dict) -> str:
    tv = state["tv"]
    md8 = facts["md5"][:8]
    tv_md5 = tv.get("md5", "")
    if tv_md5 and tv_md5 != facts["md5"]:
        tv_part = (f"**TV is on {tv['payload_version']}** (`{tv_md5[:8]}…`, "
                   f"deployed {tv['deployed_date']}) while the repo builds "
                   f"{state['repo_payload_version']}")
    else:
        tv_part = (f"**TV is on {tv['payload_version']}** (same artifact, "
                   f"deployed {tv['deployed_date']})")
    tok = tv.get("beacon_token")
    tok_part = f" every beacon carries `tok=<rootchan.token>` (live `{tok}`)" if tok else ""
    return (
        f"| Payload | repo **{state['repo_payload_version']}** (`{md8}…`, "
        f"{facts['size']:,} B; stub blob {facts['blob_size']:,} B), "
        f"deployed {tv['deployed_date']};{tok_part} forged/absent tokens are "
        f"refused by the server. {tv_part}. "
        f"{tv.get('notes', '')} |"
    )


def update_agents(row: str, fix: bool) -> int:
    text = AGENTS.read_text(encoding="utf-8")
    pattern = re.compile(re.escape(BEGIN) + r"\n(.*?)\n" + re.escape(END),
                         re.S)
    m = pattern.search(text)
    if not m:
        print("STATE block markers not found in AGENTS.md "
              "(expected STATE:BEGIN/STATE:END around the Payload row)")
        return 2
    current = m.group(1)
    if current == row:
        print("state docs up to date")
        return 0
    if not fix:
        print("state docs DRIFTED from artifacts/state.json:")
        print(f"  doc:     {current}")
        print(f"  correct: {row}")
        print("run: python tools/update_state.py --fix")
        return 1
    AGENTS.write_text(
        text[:m.start(1)] + row + text[m.end(1):], encoding="utf-8", newline="")
    print("AGENTS.md payload row updated")
    return 0


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    g = ap.add_mutually_exclusive_group(required=True)
    g.add_argument("--check", action="store_true")
    g.add_argument("--fix", action="store_true")
    argv = ap.parse_args()
    state = json.loads(STATE.read_text(encoding="utf-8"))
    return update_agents(render(state, payload_facts()), fix=argv.fix)


if __name__ == "__main__":
    sys.exit(main())
